import{tplRand,tplHash,tplHexToHsl,tplHsl}from"./sample/bytes.js";import{tplKit}from"./templates-kit.js";const TPL_WN_LEAF='M0 0C-10 -8 -28 0 -38 -10C-48 -18 -44 -30 -36 -32C-46 -38 -48 -52 -36 -56C-28 -58 -20 -52 -18 -48'+'C-20 -60 -14 -72 0 -78C14 -72 20 -60 18 -48C20 -52 28 -58 36 -56C48 -52 46 -38 36 -32C44 -30 48 -18 38 -10C28 0 10 -8 0 0Z';const TPL_WN_VEIN='M0 0L0 -70M0 -6L-33 -50M0 -6L33 -50M0 -3L-34 -15M0 -3L34 -15';function tplWnN(v){return String(Math.round(v*10)/10);}
