function tplWnRad(id,stops,o={}){const u=o.user?' gradientUnits="userSpaceOnUse"':'';const f=o.fx!=null?' fx="'+o.fx+'" fy="'+o.fy+'"':'';return'<radialGradient id="'+id+'" cx="'+(o.cx??0.5)+'" cy="'+(o.cy??0.5)+'" r="'+(o.r??0.5)+'"'+f+u+'>'+tplWnStops(stops)+'</radialGradient>';}
