if(mode!=='night'){for(let i=0;i<5;i++){const x=w*(0.12+rnd()*0.4),y=hz*(0.3+rnd()*0.35),s2=(5+rnd()*6)*sc;b+='<path d="M'+N(x)+' '+N(y)+'q'+N(s2)+' '+N(-s2*0.8)+' '+N(s2*2)+' 0q'+N(s2)+' '+N(-s2*0.8)+' '+N(s2*2)+' 0" fill="none" stroke="'+P.bird+'" stroke-width="'+N(1.6*sc)+'" stroke-linecap="round"/>';}}
